import { CalendarDays, CarFront, ChevronDown, Clock3, MapPin, Route, ShieldCheck, Sparkles, Users } from '@lucide/vue';

interface Vehicle { id:number; name:string; brand:string; model:string; type:string|null; seats:number; image:string|null; price:string|number; }
defineProps<{ vehicles: Vehicle[] }>();
const mode = ref<'ride'|'rental'|'tour'>('ride');
const tripType = ref<'one-way'|'round-trip'>('one-way');
const pickup = ref('');
const destination = ref('');
const pickupDate = ref('');
const pickupTime = ref('09:00');
const rentalDays = ref(1);
const passengers = ref(2);
const submitLabel = () => mode.value === 'ride' ? 'Tìm chuyến xe' : mode.value === 'rental' ? 'Thuê xe ngay' : 'Khám phá tour';
const formatPrice = (price:string|number) => `${Number(price).toLocaleString('vi-VN')}đ/ngày`;
const bookingUrl = () => {
    const params = new URLSearchParams();
    if (pickup.value) params.set('pickup', pickup.value);
    if (destination.value) params.set('destination', destination.value);
    if (pickupDate.value) params.set('date', pickupDate.value);
    if (pickupTime.value) params.set('time', pickupTime.value);
    params.set('passengers', String(passengers.value));
    return `/dat-xe${params.toString() ? `?${params.toString()}` : ''}`;
};
const rentalUrl = () => {
    const params = new URLSearchParams();
    if (pickup.value) params.set('pickup', pickup.value);
    if (destination.value) params.set('destination', destination.value);
    if (pickupDate.value) params.set('date', pickupDate.value);
    params.set('days', String(rentalDays.value));
    params.set('passengers', String(passengers.value));
    return `/thue-xe${params.toString() ? `?${params.toString()}` : ''}`;
};
</script>

